// intent: Verify that json::accept agrees with parse(..., allow_exceptions=false) on arbitrary inputs.
#include <nlohmann/json.hpp>
#include <iostream>
int main() {
    std::string inputs[] = {
        "{\"a\": 1}",
        "{\"a\": 1,",
        "[true, false, null]",
        "\"just a string\"",
        "42",
        "invalid"
    };
    for (const auto& in : inputs) {
        bool acc = nlohmann::json::accept(in);
        auto p = nlohmann::json::parse(in, nullptr, false);
        bool parsed_ok = !p.is_discarded();
        std::cout << (acc == parsed_ok) << std::endl;
    }
    return 0;
}
